from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.mobile.gnb.oam.coam.classical.pages.navigatable_page import NavigatablePage
from taf.selenium.mobile.gnb.oam.coam.classical.pages.modals import ResetModal


class SiteViewPage(NavigatablePage):
    """
    As a class will be called by BtsStatus, all operations on Detailed Site View will be implemented under this class.
    """
    BASIC_INFO_XPATH = '//div[@class ="option-menu"]'
    BTS_CONNECTION_STATUS_XPATH = '//connection-status/div'
    BTS_ID_XPATH = '//span[text()="BTS ID:"]/following-sibling::div'
    BTS_NAME_XPATH = '//span[text()="BTS name:"]/following-sibling::div'
    BTS_SW_VERSION_XPATH = '//span[text()="SW version:"]/following-sibling::a//span'
    BTS_TIMEZONE_XPATH = '//status-bar-timezone/span'
    BTS_ALARMS_NUMBER_XPATH = '//span[text()="Alarms total number:"]/following-sibling::div'
    BTS_STATE_XPATH = '//cells-status//div[contains(@class, "nbts")]'
    BTS_CELLS_STATUS_XPATH = '//div[contains(@class, "cells-status-svg")]'
    BTS_CELLS_STATUS_INFO_XPATH = '//div[contains(@class, "cells-status-info")]'
    RESET_SITE_BUTTON_XPATH = "//ui-button[@a-text='Reset Site']/button"
    BASE_HW_XPATH = '//div[contains(text(), "{}")]/parent::div/preceding-sibling::div/span'
    RESET_HW_BUTTON_XPATH = '//button[@title="Reset"]'

    def __init__(self, tool):
        super(SiteViewPage, self).__init__(tool)

    def get_bts_basic_info(self):
        self._tool.wait_until_element_is_clickable(self.BASIC_INFO_XPATH)
        self._tool.click_enabled_element_after_visible((By.XPATH, self.BASIC_INFO_XPATH))

        bts_connection_status = self._tool.get_attribute_by_xpath(self.BTS_CONNECTION_STATUS_XPATH, 'class')
        bts_id = self._tool.get_text_by_xpath(self.BTS_ID_XPATH)
        bts_name = self._tool.get_text_by_xpath(self.BTS_NAME_XPATH)
        bts_sw_version = self._tool.get_text_by_xpath(self.BTS_SW_VERSION_XPATH)
        bts_timezone = self._tool.get_text_by_xpath(self.BTS_TIMEZONE_XPATH)
        bts_alarms_number = self._tool.get_text_by_xpath(self.BTS_ALARMS_NUMBER_XPATH)
        bts_state = self._tool.get_text_by_xpath(self.BTS_STATE_XPATH)
        bts_cells_status = self._tool.get_attribute_by_xpath(self.BTS_CELLS_STATUS_XPATH, 'title')
        bts_cells_status_info = self._tool.get_text_by_xpath(self.BTS_CELLS_STATUS_INFO_XPATH)
        basic_info_dict = {
            'bts connection status': bts_connection_status,
            'BTS ID:': bts_id,
            'BTS name:': bts_name,
            'SW version:': bts_sw_version,
            'timezone': bts_timezone,
            'Alarms total number:': bts_alarms_number,
            'nbts operational state': bts_state,
            'bts cells status': bts_cells_status,
            'bts cells status info': bts_cells_status_info
        }
        return basic_info_dict

    def close_bts_basic_info(self):
        option_menu_js = 'document.querySelector("div.option-menu>i").click()'
        self._tool.driver.execute_script(option_menu_js)

    def reset_hardware(self, hw_name, timeout):
        hw_xpath = self.BASE_HW_XPATH.format(hw_name)
        self._tool.wait_until_element_is_clickable(hw_xpath)
        self._tool.click_enabled_element_after_visible((By.XPATH, hw_xpath), timeout)
        self._tool.wait_until_element_is_clickable(self.RESET_HW_BUTTON_XPATH)
        self._tool.click_enabled_element_after_visible((By.XPATH, self.RESET_HW_BUTTON_XPATH), timeout)
        reset_hardware_modal = ResetModal(self._tool)
        reset_hardware_modal.wait_until_reset_modal_appear()
        reset_hardware_modal.confirm()

    def reset_site(self):
        self._tool.wait_until_element_is_clickable(self.RESET_SITE_BUTTON_XPATH)
        self._tool.click_enabled_element_after_visible((By.XPATH, self.RESET_SITE_BUTTON_XPATH))
        reset_site_modal = ResetModal(self._tool)
        reset_site_modal.wait_until_reset_modal_appear()
        reset_site_modal.confirm()
